input.script:
// Tarea 3 del workflow "Análisis de causa raíz": valida la respuesta de la IA.
// - Solo acepta ids de problemas que estaban en el contexto (anti-alucinación).
// - Cada problema queda en UN solo lugar: causa raíz, efecto de una causa, o sin clasificar.
// Salida: { ok, version, generadoEn, causasRaiz:[{problemId, razon, confianza, efectos, evidencia}],
//           sinClasificar, resumen, descartados,
//           problemas: { [event.id]: { displayId, nombre, categoria, inicio, nodos } } }
// ← esto es lo que lee la app (con `problemas` pinta la leyenda y el modal sin consultar nada más).
import { execution } from "@dynatrace-sdk/automation-utils";
import { executionsClient } from "@dynatrace-sdk/client-automation";

// Mensaje fijo de la plataforma cuando el agente agota su tope de llamadas a
// herramientas (lo reporta como SUCCESS con este texto; patrón del workflow
// oficial «SRE Agent»).
const TOPE_HERRAMIENTAS = "maximum number of tool calls has been reached";

const arr = (v) => (Array.isArray(v) ? v : []);
// Horas "HH:MM UTC" (o "HH:MM:SS UTC") → hora de Colombia (UTC-5), sin "UTC".
// La IA no siempre las convierte; esto lo hace de forma determinista.
const toCol = (t) =>
  t.replace(/\b(\d{1,2}):(\d{2})(?::\d{2})?\s*UTC\b/g, (_, h, m) => `${String((Number(h) + 19) % 24).padStart(2, "0")}:${m}`);
const txt = (v, max = 1500) => (typeof v === "string" ? toCol(v.trim()).slice(0, max) : "");

const parse = (v) => {
  if (v && typeof v === "object") return v;
  if (typeof v !== "string") return null;
  const s = v.trim().replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "");
  try {
    return JSON.parse(s);
  } catch {
    const i = s.indexOf("{");
    const j = s.lastIndexOf("}");
    if (i >= 0 && j > i) {
      try {
        return JSON.parse(s.slice(i, j + 1));
      } catch {
        /* sigue */
      }
    }
    return null;
  }
};


// ── Confianza CALCULADA (no la que se pone la IA) ────────────────────────────
// Por cada relación causa → efecto propuesta, se revisan 6 señales comprobables
// con datos del contexto. null = no hay datos para evaluarla (no cuenta).
//   topologia     relación real en Smartscape entre sus entidades (o comparten entidad)
//   orden         la causa empezó antes o a la vez (±5 min); si empezó DESPUÉS → contradicción
//   raizDavis     la entidad raíz que Davis da al efecto es una entidad de la causa
//   eventos       los dos problemas comparten eventos de Davis
//   entorno       mismo clúster+namespace o mismo host
//   conexionMapa  en el mapa, el nodo del efecto apunta (depende) al nodo de la causa
// Nivel: ≥4 → alta, 2–3 → media, ≤1 → baja; con contradicción de orden → baja.
const SENALES = ["topologia", "orden", "raizDavis", "eventos", "entorno", "conexionMapa"];
const minutos = (s) => {
  const t = typeof s === "string" ? Date.parse(s.replace(" ", "T") + ":00Z") : NaN;
  return Number.isNaN(t) ? null : t / 60000;
};
const evidencia = (C, ctx) => {
  const P = new Map(arr(C.problemas).map((p) => [String(p.id), p]));
  const ent = C.entidades || {};
  const rel = new Set(arr(C.relacionesSmartscape));
  const conex = new Set(arr(C.mapa?.conexiones));
  const evs = ctx.eventosPorProblema || {};
  const ents = (p) => new Set([...arr(p?.entidadesAfectadas), p?.entidadRaizDavis?.id].filter(Boolean).map(String));
  const relacionadas = (A, B) => {
    for (const a of A) {
      if (B.has(a)) return true;
      for (const b of B) {
        for (const r of rel) {
          if ((r.startsWith(a + " ") && r.endsWith(" " + b)) || (r.startsWith(b + " ") && r.endsWith(" " + a))) return true;
        }
      }
    }
    return false;
  };
  const entorno = (A, B) => {
    const k = (id) => {
      const e = ent[id];
      return e ? [e.cluster && e.namespace ? `ns:${e.cluster}/${e.namespace}` : null, e.host ? `h:${e.host}` : null].filter(Boolean) : [];
    };
    const ka = new Set([...A].flatMap(k));
    const kb = [...B].flatMap(k);
    if (!ka.size || !kb.length) return null;
    return kb.some((x) => ka.has(x));
  };
  return (causaId, efectoId) => {
    const c = P.get(causaId);
    const e = P.get(efectoId);
    const A = ents(c);
    const B = ents(e);
    const tc = minutos(c?.inicio);
    const te = minutos(e?.inicio);
    const contradice = tc != null && te != null && tc > te + 5;
    const evC = new Set(arr(evs[causaId]));
    const evE = arr(evs[efectoId]);
    const nC = arr(c?.nodosDelMapa);
    const nE = arr(e?.nodosDelMapa);
    const senales = {
      topologia: A.size && B.size ? relacionadas(A, B) : null,
      orden: tc != null && te != null ? !contradice : null,
      raizDavis: e?.entidadRaizDavis?.id ? A.has(String(e.entidadRaizDavis.id)) : null,
      eventos: evC.size && evE.length ? evE.some((x) => evC.has(x)) : null,
      entorno: entorno(A, B),
      conexionMapa: nC.length && nE.length ? nE.some((x) => nC.some((y) => conex.has(`${x} -> ${y}`))) : null,
    };
    const evaluadas = SENALES.filter((k) => senales[k] !== null);
    const puntaje = evaluadas.filter((k) => senales[k] === true).length;
    const nivel = contradice ? "baja" : puntaje >= 4 ? "alta" : puntaje >= 2 ? "media" : "baja";
    return { puntaje, total: evaluadas.length, nivel, contradice, senales };
  };
};

export default async function ({ execution_id }) {
  const ex = await execution(execution_id);
  const ctx = await ex.result("contexto");
  if (!ctx?.ok) return { ok: false, reason: ctx?.reason || "sin-contexto" };
  const valid = new Set(arr(ctx.problemIds).map(String));
  // Nombres reales de los nodos que se enmascararon para la IA (ver contexto.js):
  // se devuelven en el texto final (app y comentarios), nunca a la IA.
  const reales = Object.entries(ctx.nombresReales || {}).sort((a, b) => b[0].length - a[0].length);
  const real = (t) => (typeof t === "string" ? reales.reduce((acc, [m, r]) => acc.split(m).join(r), t) : t);

  // Fallas de la IA con motivo claro (en vez de "respuesta inválida"):
  // la tarea falló, agotó el tope de herramientas o respondió vacío.
  let ai = null;
  try {
    ai = await ex.result("analisis");
  } catch {
    ai = null;
  }
  if (!ai) {
    let detalle = "";
    try {
      const t = await executionsClient.getTaskExecution({ executionId: execution_id, id: "analisis" });
      detalle = t.stateInfo || "";
    } catch {
      /* sin detalle */
    }
    return { ok: false, reason: "ia-error", detalle: String(detalle).slice(0, 300) };
  }
  const texto = typeof ai.text === "string" ? ai.text : "";
  if (texto.includes(TOPE_HERRAMIENTAS)) return { ok: false, reason: "ia-tope-herramientas" };
  if (!ai.jsonOutput && !texto.trim()) return { ok: false, reason: "ia-sin-respuesta" };
  const out = parse(ai?.jsonOutput ?? ai?.output ?? ai?.text ?? ai);
  if (!out || !Array.isArray(out.causasRaiz)) {
    return { ok: false, reason: "respuesta-invalida", llaves: Object.keys(ai || {}), muestra: JSON.stringify(ai).slice(0, 1500) };
  }

  const roots = [];
  const isRoot = new Set();
  let descartados = 0;
  for (const c of out.causasRaiz) {
    const id = String(c?.problemId ?? "");
    if (!valid.has(id) || isRoot.has(id)) {
      descartados++;
      continue;
    }
    isRoot.add(id);
    roots.push({
      problemId: id,
      veredicto: real(txt(c.veredicto, 400)),
      razon: real(txt(c.razon)),
      recomendaciones: arr(c.recomendaciones).map((r) => real(txt(r, 300))).filter(Boolean).slice(0, 5),
      confianza: ["alta", "media", "baja"].includes(c?.confianza) ? c.confianza : "baja",
      efectos: arr(c.efectos).map(String),
      evidencia: arr(c.evidencia).map((e) => real(txt(e, 400))).filter(Boolean).slice(0, 8),
    });
  }
  const asignado = new Set();
  for (const r of roots) {
    const ef = r.efectos.filter((id) => valid.has(id) && !isRoot.has(id) && !asignado.has(id));
    descartados += r.efectos.length - ef.length;
    ef.forEach((id) => asignado.add(id));
    r.efectos = ef;
  }
  const sinClasificar = [...valid].filter((id) => !isRoot.has(id) && !asignado.has(id));
  // Datos de presentación de cada problema, tomados del MISMO contexto que vio la IA.
  const problemas = {};
  try {
    for (const p of JSON.parse(ctx.contextJson || "{}").problemas || []) {
      problemas[String(p.id)] = {
        displayId: p.displayId,
        nombre: p.nombre,
        categoria: p.categoria,
        inicio: p.inicio,
        nodos: arr(p.nodosDelMapa).map(String).map(real),
      };
    }
  } catch {
    /* sin metadatos: la app muestra el id */
  }
  // Confianza calculada por cada causa (promedio de sus relaciones con efectos).
  let C = {};
  try {
    C = JSON.parse(ctx.contextJson || "{}");
  } catch {
    C = {};
  }
  const ev = evidencia(C, ctx);
  const orden = { baja: 0, media: 1, alta: 2 };
  for (const r of roots) {
    const rels = r.efectos.map((id) => ({ efecto: id, ...ev(r.problemId, id) }));
    r.evidenciaCalc = rels;
    if (!rels.length) r.confianzaCalc = null; // causa aislada: no explica otros problemas
    else {
      const prom = rels.reduce((a, x) => a + orden[x.nivel], 0) / rels.length;
      r.confianzaCalc = prom >= 1.5 ? "alta" : prom >= 0.75 ? "media" : "baja";
    }
  }

  return {
    ok: true,
    version: 1,
    generadoEn: new Date().toISOString(),
    causasRaiz: roots,
    sinClasificar,
    resumen: real(txt(out.resumen, 800)),
    descartados,
    problemas,
  };
}

// Tarea del workflow "Análisis de causa raíz": comentario de PROGRESO.
// Apenas se arma el contexto, cada problema del mapa recibe «⏳ Análisis en
// curso». Al terminar, la tarea "anotar" lo REEMPLAZA (mismo annotationId) por
// el resultado: causa raíz, efecto, sin clasificar o el motivo de la falla.
// Patrón del workflow oficial «SRE Agent». Solo si input.comentar === true.
import { execution } from "@dynatrace-sdk/automation-utils";

const arr = (v) => (Array.isArray(v) ? v : []);

export default async function ({ execution_id }) {
  try {
    const ex = await execution(execution_id);
    const inp = { ...(ex.params || {}), ...(ex.input || {}) };
    if (inp.comentar !== true) return { lista: [] };
    const ctx = await ex.result("contexto");
    if (!ctx?.ok) return { lista: [] };
    const mapa = String(inp.mapName || "sin nombre").slice(0, 120);
    // MISMOS fuente y annotationId que en comentar.js (si no, no se reemplaza).
    const quien = String(inp.requestedBy || "").trim().slice(0, 80);
    const fuente = `Mapas de Servicios V2 · ${mapa}${quien ? ` · ${quien}` : ""}`.slice(0, 150);
    const cuando = new Date().toLocaleString("es-CO", { timeZone: "America/Bogota", dateStyle: "short", timeStyle: "short" });
    const mapKey = String(inp.mapId || mapa).replace(/[^A-Za-z0-9-]/g, "").slice(0, 40);
    const solo = arr(inp.comentarSoloIds).map(String);
    const texto = [
      quien ? `👤 **Solicitado por:** ${quien} · ${cuando}` : `🕘 **Análisis:** ${cuando}`,
      "",
      "### ⏳ Análisis de causa raíz en curso",
      `**Mapa:** ${mapa}`,
      "",
      "Dynatrace Intelligence está analizando los problemas de este mapa. Este comentario se actualizará con el resultado en uno o dos minutos.",
      "",
      "---",
      "_Mapas de Servicios V2_",
    ].join("\n");
    const items = arr(ctx.problemIds)
      .map(String)
      .filter((id) => !solo.length || solo.includes(id))
      .map((problemId) => ({ problemId, annotationId: `mapas-v2-${mapKey}-${problemId}`, source: fuente, text: texto }));
    return { lista: items };
  } catch {
    return { lista: [] };
  }
}

// Tarea 4 del workflow "Análisis de causa raíz": ARMA los comentarios (markdown)
// que la tarea 5 ("anotar", acción oficial «Annotate & Link» de la app Problems)
// publica en cada problema. Así quien abra el problema en la app Problems ya ve
// el pre-análisis:
//   - Causa raíz → el mismo contenido del modal de la app.
//   - Efecto → nota que apunta a su causa raíz.
// Un comentario por problema y por mapa: se actualiza en cada análisis
// (mismo `annotationId`).
// Solo corre si la app lo pide (input.comentar === true). Nunca hace fallar el
// workflow. Prueba controlada: `comentarSoloIds` limita a esos problemas.
import { execution } from "@dynatrace-sdk/automation-utils";
import { getEnvironmentUrl } from "@dynatrace-sdk/app-environment";

const MAX_CHARS = 4800;
const arr = (v) => (Array.isArray(v) ? v : []);
const enCol = (iso) => {
  try {
    return new Date(iso).toLocaleString("es-CO", { timeZone: "America/Bogota", dateStyle: "short", timeStyle: "short" });
  } catch {
    return "";
  }
};

export default async function ({ execution_id }) {
  try {
    const ex = await execution(execution_id);
    const inp = { ...(ex.params || {}), ...(ex.input || {}) };
    if (inp.comentar !== true) return { ok: true, omitido: "comentarios-apagados", lista: [] };
    const res = await ex.result("resultado").catch(() => null);
    const ctx = await ex.result("contexto").catch(() => null);
    // Metadatos de cada problema: del resultado o, si el análisis falló, del contexto.
    let P = res?.problemas || {};
    if (!res?.ok) {
      P = {};
      // Sin resultado: los nombres vienen del contexto enmascarado → restaurarlos.
      const reales = Object.entries(ctx?.nombresReales || {}).sort((a, b) => b[0].length - a[0].length);
      const real = (t) => reales.reduce((acc, [m, r]) => acc.split(m).join(r), t);
      try {
        for (const p of JSON.parse(ctx?.contextJson || "{}").problemas || []) {
          P[String(p.id)] = { displayId: p.displayId, nombre: p.nombre, nodos: arr(p.nodosDelMapa).map(String).map(real) };
        }
      } catch {
        /* sin metadatos */
      }
    }
    const mapa = String(inp.mapName || "sin nombre").slice(0, 120);
    // Se ve en la app como «via …» y sirve para reconocer los comentarios de este mapa.
    // Quién pidió el análisis (lo manda la app). El autor del comentario en
    // Problems es siempre el actor del workflow; por eso el nombre va en el texto.
    const quien = String(inp.requestedBy || "").trim().slice(0, 80);
    const fuente = `Mapas de Servicios V2 · ${mapa}${quien ? ` · ${quien}` : ""}`.slice(0, 150);
    const cuando = enCol(res?.generadoEn || new Date().toISOString());
    // Primera línea de todos los comentarios: quién lo solicitó y cuándo.
    const cabeza = quien ? `👤 **Solicitado por:** ${quien} · ${cuando}` : `🕘 **Análisis:** ${cuando}`;
    // Prueba controlada: si viene `comentarSoloIds`, solo se comentan esos problemas.
    const solo = arr(inp.comentarSoloIds).map(String);
    const permitido = (id) => !solo.length || solo.includes(id);
    let base = "";
    try {
      base = getEnvironmentUrl().replace(/\/$/, "");
    } catch {
      base = "";
    }
    const link = (id) => {
      const etiqueta = `**${P[id]?.displayId || id}**`;
      return base ? `[${etiqueta}](${base}/ui/apps/dynatrace.davis.problems/problem/${encodeURIComponent(id)})` : etiqueta;
    };
    const nodos = (id) => arr(P[id]?.nodos).join(", ");
    const datos = (id) =>
      [`**Mapa:** ${mapa}`, nodos(id) ? `**Nodo:** ${nodos(id)}` : ""].filter(Boolean).join(" · ");
    const conf = { alta: "🟢 Alta", media: "🟡 Media", baja: "🟠 Baja" };
    const SENAL = {
      topologia: "Relación en Smartscape",
      orden: "Orden en el tiempo",
      raizDavis: "Raíz según Davis",
      eventos: "Eventos compartidos",
      entorno: "Mismo clúster o host",
      conexionMapa: "Conexión del mapa",
    };
    const evDe = (c, id) => arr(c.evidenciaCalc).find((x) => x.efecto === id);
    const confTxt = (c) =>
      c.confianzaCalc === null
        ? "⚪ Causa aislada (no explica otros problemas del mapa)"
        : c.confianzaCalc
          ? `${conf[c.confianzaCalc]} · calculada con evidencia verificable`
          : conf[c.confianza] || c.confianza;
    const senalesTxt = (x) =>
      Object.entries(SENAL)
        .filter(([k]) => x.senales?.[k] === true || x.senales?.[k] === false)
        .map(([k, nombre]) => `${x.senales[k] ? "✔" : "✖"} ${nombre}`)
        .join(" · ");
    const pie = "_Pre-análisis generado por Dynatrace Intelligence desde Mapas de Servicios V2. Se actualiza en cada análisis del mapa._";

    const mensajes = new Map();
    // Análisis fallido: cada problema recibe el motivo (reemplaza su «⏳»).
    if (!res?.ok) {
      const motivos = {
        "ia-tope-herramientas": "la IA alcanzó su tope de consultas antes de terminar",
        "ia-sin-respuesta": "la IA no devolvió respuesta",
        "ia-error": `la IA falló${res?.detalle ? ` (${res.detalle})` : ""}`,
        "respuesta-invalida": "la respuesta de la IA no fue válida",
      };
      for (const id of arr(ctx?.problemIds).map(String)) {
        if (!permitido(id)) continue;
        mensajes.set(
          id,
          [
            cabeza,
            "",
            "### ⚠️ Análisis de causa raíz sin resultado",
            datos(id),
            "",
            `El análisis no pudo completarse: ${motivos[res?.reason] || "error inesperado"}. Vuelve a analizar desde el mapa.`,
            "",
            "---",
            pie,
          ].join("\n"),
        );
      }
    }
    for (const c of arr(res?.causasRaiz)) {
      const efectos = arr(c.efectos);
      // Orden: veredicto → por qué → qué hacer → efectos → evidencia.
      const l = [cabeza, "", "### 🔴 Causa raíz", datos(c.problemId), ""];
      if (c.veredicto) l.push(`> **${c.veredicto}**`, "");
      l.push("#### Por qué es causa raíz", c.razon, "", `**Confianza:** ${confTxt(c)} · _la IA la calificó: ${c.confianza}_`);
      if (arr(c.recomendaciones).length) {
        l.push("", "#### Qué hacer");
        arr(c.recomendaciones).forEach((r, i) => l.push(`${i + 1}. ${r}`));
      }
      if (efectos.length) {
        l.push("", `#### Efectos que explica (${efectos.length})`);
        for (const e of efectos) {
          const x = evDe(c, e);
          l.push(`- ${link(e)} · ${P[e]?.nombre || "problema"}${nodos(e) ? ` · nodo _${nodos(e)}_` : ""}${x ? ` · evidencia ${x.puntaje}/${x.total}` : ""}`);
        }
      }
      if (arr(c.evidencia).length) {
        l.push("", "#### Evidencia");
        for (const v of c.evidencia) l.push(`- ${v}`);
      }
      l.push("", "---", pie);
      if (permitido(c.problemId)) mensajes.set(c.problemId, l.join("\n"));
      for (const e of efectos) {
        if (!permitido(e)) continue;
        mensajes.set(
          e,
          [
            cabeza,
            "",
            "### 🔗 Efecto de otra causa raíz",
            datos(e),
            "",
            `> Este problema es **consecuencia** de ${link(c.problemId)} · ${P[c.problemId]?.nombre || "problema"}${nodos(c.problemId) ? ` (nodo _${nodos(c.problemId)}_)` : ""}. **Atiende primero la causa raíz:** su comentario tiene el detalle y qué hacer.`,
            "",
            ...(evDe(c, e)
              ? [`**Evidencia de la relación (${evDe(c, e).puntaje} de ${evDe(c, e).total}):** ${senalesTxt(evDe(c, e))}`, ""]
              : []),
            ...(c.veredicto ? ["#### Qué pasó en la causa raíz", c.veredicto, ""] : []),
            "#### Por qué este problema es efecto",
            c.razon,
            "",
            "---",
            pie,
          ].join("\n"),
        );
      }
    }

    // Sin clasificar: nota breve (reemplaza su «⏳»).
    for (const id of arr(res?.sinClasificar).map(String)) {
      if (!permitido(id) || mensajes.has(id)) continue;
      mensajes.set(
        id,
        [
          cabeza,
            "",
            "### ⚪ Sin clasificar",
          datos(id),
          "",
          "El análisis del mapa no encontró evidencia suficiente para saber si este problema es causa raíz o efecto de otro. Revísalo por separado.",
          "",
          "---",
          pie,
        ].join("\n"),
      );
    }

    // `annotationId` fijo por mapa y problema: «Annotate & Link» con el mismo id
    // ACTUALIZA el comentario en vez de crear otro (patrón del workflow oficial
    // «SRE Agent»). Así cada análisis del mapa reemplaza al anterior.
    const mapKey = String(inp.mapId || mapa).replace(/[^A-Za-z0-9-]/g, "").slice(0, 40);
    const items = [];
    for (const [problemId, texto] of mensajes) {
      items.push({ problemId, annotationId: `mapas-v2-${mapKey}-${problemId}`, source: fuente, text: texto.slice(0, MAX_CHARS) });
    }
    const omitidos = 0;
    return { ok: true, lista: items, omitidos };
  } catch (e) {
    return { ok: false, reason: String(e?.message || e).slice(0, 300), lista: [] };
  }
}
